package de.tekatz.foreverskyblock.editor;

import com.google.gson.*;
import de.tekatz.foreverskyblock.progression.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import static de.tekatz.foreverskyblock.editor.EditorDocument.*;

class EditorRulesTest {
    @TempDir Path temp;
    @AfterEach void cleanup(){EditorRuntime.publish(null);}
    private Quest quest(String name,List<Task> tasks,Match match,List<String> parents,Match prerequisites){return new Quest("forever_skyblock:quest/"+name,true,new Text(name,name),new Text("Description","Beschreibung"),"minecraft:book","forever",tasks,match,parents,prerequisites,-1,3,1);}
    private EditorDocument with(Quest...quests){var d=EditorDefaults.create();var q=new ArrayList<>(d.quests());q.addAll(List.of(quests));return new EditorDocument(d.schema(),d.revision(),d.layout(),d.chapters(),q,d.products(),d.contracts(),d.nodes(),d.decorations(),d.settings());}
    private Task task(String id,TaskType type,String target,int n){return new Task(id,type,target,n);}
    private QuestRules.Event craft(int n){return new QuestRules.Event(TaskType.CRAFT,"minecraft:mud_bricks",n,"");}
    @Test void defaultsRoundTripPreservesEveryOriginalChallengeRewardAndContract(){var d=EditorDefaults.create();assertEquals(d,EditorCodec.decode(EditorCodec.encode(d)));for(var original:ChallengeRules.ALL){var q=d.quest(original.id());assertTrue(q.legacy());assertEquals(original.target(),q.tasks().getFirst().count());assertEquals(original.reward(),q.rewardSp());}assertEquals(58,d.quests().stream().mapToInt(Quest::rewardSp).sum());assertEquals(ContractCatalog.CONTRACTS.size(),d.contracts().size());}
    @Test void rejectsCyclesMissingPrerequisitesDuplicatesAndOversizedJson(){var a=quest("a",List.of(task("a",TaskType.CRAFT,"minecraft:mud_bricks",1)),Match.ALL,List.of("forever_skyblock:quest/b"),Match.ALL);var b=quest("b",a.tasks(),Match.ALL,List.of(a.id()),Match.ALL);assertThrows(IllegalArgumentException.class,()->EditorCodec.validate(with(a,b)));assertThrows(IllegalArgumentException.class,()->EditorCodec.validate(with(a)));assertThrows(IllegalArgumentException.class,()->EditorCodec.validate(with(b,b)));assertThrows(IllegalArgumentException.class,()->EditorCodec.decode(" ".repeat(MAX_BYTES+1)));}
    @Test void multiObjectiveCountsAreClampedAndRewardIsAtomicExactlyOnce(){var q=quest("bricks",List.of(task("bricks",TaskType.CRAFT,"minecraft:mud_bricks",256),task("kill",TaskType.KILL,"minecraft:zombie",2)),Match.ALL,List.of(),Match.ALL);var d=with(q);var p=QuestRules.record(ProgressionProfile.empty(),d,craft(300));assertEquals(256,QuestRules.counts(q,p).get("bricks"));assertEquals(0,p.points());var kill=new QuestRules.Event(TaskType.KILL,"minecraft:zombie",1,"h/"+UUID.randomUUID());p=QuestRules.record(p,d,kill);assertEquals(p,QuestRules.record(p,d,kill));p=QuestRules.record(p,d,new QuestRules.Event(TaskType.KILL,"minecraft:zombie",1,"h/"+UUID.randomUUID()));assertEquals(3,p.points());assertEquals(1,p.perkPoints());assertEquals(3,p.meta().accounting().spEarned());assertEquals(p,QuestRules.record(p,d,craft(100)));}
    @Test void hostileAndSpecificObjectivesCanUseTheSameAuthoritativeKill(){var q=quest("kills",List.of(task("specific",TaskType.KILL,"minecraft:zombie",1),task("hostile",TaskType.KILL,"minecraft:any_hostile",1)),Match.ALL,List.of(),Match.ALL);var p=QuestRules.record(ProgressionProfile.empty(),with(q),new QuestRules.Event(TaskType.KILL,"minecraft:zombie",1,"h/"+UUID.randomUUID()));assertTrue(p.milestones().contains(q.id()));}
    @Test void allAndAnyPrerequisitesDoNotCountTheUnlockingEventTwice(){var a=quest("a",List.of(task("a",TaskType.CRAFT,"minecraft:mud_bricks",1)),Match.ALL,List.of(),Match.ALL);var b=quest("b",a.tasks(),Match.ALL,List.of(a.id()),Match.ALL);var d=with(a,b);var p=QuestRules.record(ProgressionProfile.empty(),d,craft(1));assertTrue(p.milestones().contains(a.id()));assertFalse(p.milestones().contains(b.id()));assertFalse(QuestRules.counts(b,p).get("a")>0);p=QuestRules.record(p,d,craft(1));assertTrue(p.milestones().contains(b.id()));assertTrue(QuestRules.dependencies(List.of(a.id(),"forever_skyblock:missing"),Match.ANY,p.milestones()));assertFalse(QuestRules.dependencies(List.of(a.id(),"forever_skyblock:missing"),Match.ALL,p.milestones()));}
    @Test void anyObjectiveAndDisabledQuestRespectTheirRules(){var q=quest("any",List.of(task("a",TaskType.CRAFT,"minecraft:mud_bricks",2),task("b",TaskType.PICKUP,"minecraft:diamond",1)),Match.ANY,List.of(),Match.ALL);var d=with(q);var p=QuestRules.record(ProgressionProfile.empty(),d,craft(2));assertTrue(p.milestones().contains(q.id()));var json=EditorCodec.JSON.toJsonTree(d).getAsJsonObject();json.getAsJsonArray("quests").get(json.getAsJsonArray("quests").size()-1).getAsJsonObject().addProperty("enabled",false);assertEquals(ProgressionProfile.empty(),QuestRules.record(ProgressionProfile.empty(),EditorCodec.decode(json.toString()),craft(10)));}
    @Test void customProgressAndRewardsSurviveRealProfilePersistenceAndRespec()throws Exception{var q=quest("persist",List.of(task("a",TaskType.CRAFT,"minecraft:mud_bricks",5)),Match.ALL,List.of(),Match.ALL);var d=with(q);UUID id=UUID.randomUUID();var store=new ProfileStore(temp);store.update(id,p->QuestRules.record(p,d,craft(3)));store=new ProfileStore(temp);assertEquals(3,QuestRules.counts(q,store.load(id)).get("a"));store.update(id,p->QuestRules.record(p,d,craft(2)));var loaded=new ProfileStore(temp).load(id);assertEquals(3,loaded.points());assertEquals(1,loaded.perkPoints());assertTrue(loaded.resetSkills(Map.of()).milestones().contains(q.id()));assertEquals(loaded,QuestRules.record(loaded,d,craft(100)));}
    @Test void publicationProtectsIdentityAndExistingPaidPackageContents(){var d=EditorDefaults.create();var json=EditorCodec.JSON.toJsonTree(d).getAsJsonObject();json.getAsJsonArray("quests").remove(0);var removed=EditorCodec.decode(json.toString());assertThrows(IllegalArgumentException.class,()->EditorCodec.validateUpdate(d,removed));json=EditorCodec.JSON.toJsonTree(d).getAsJsonObject();json.getAsJsonArray("products").get(1).getAsJsonObject().getAsJsonArray("contents").get(0).getAsJsonObject().addProperty("count",64);var changed=json.toString();assertThrows(IllegalArgumentException.class,()->EditorCodec.decode(changed));}
    @Test void changedRewardDoesNotReplayCompletedQuest(){var q=quest("reward",List.of(task("a",TaskType.CRAFT,"minecraft:mud_bricks",1)),Match.ALL,List.of(),Match.ALL);var d=with(q);var p=QuestRules.record(ProgressionProfile.empty(),d,craft(1));var json=EditorCodec.JSON.toJsonTree(d).getAsJsonObject();json.getAsJsonArray("quests").get(json.getAsJsonArray("quests").size()-1).getAsJsonObject().addProperty("rewardSp",999);var next=EditorCodec.decode(json.toString());EditorCodec.validateUpdate(d,next);assertEquals(p,QuestRules.record(p,next,craft(1)));}
    @Test void atomicBackupAndExportChecksumRoundTrip()throws Exception{var a=EditorDefaults.create();var b=a.withRevision(1);var store=new EditorStore(temp.resolve("kmenu.json"));store.save(a);store.save(b);assertEquals(a,store.readBackup());assertEquals(b,store.load());Path zip=temp.resolve("export.zip");EditorStore.exportZip(b,zip);assertEquals(b,EditorStore.importZip(zip));try(var out=new ZipOutputStream(Files.newOutputStream(temp.resolve("bad.zip")))){out.putNextEntry(new ZipEntry("../../escape.json"));out.write("{}".getBytes());out.closeEntry();}assertThrows(java.io.IOException.class,()->EditorStore.importZip(temp.resolve("bad.zip")));assertFalse(Files.exists(temp.getParent().resolve("escape.json")));}
    @Test void historyAndSnapHavePredictableGestureBoundaries(){var d=EditorDefaults.create();var s=new EditorSession(d);s.replace(d.withRevision(1));s.undo();assertEquals(d,s.current());s.redo();assertEquals(1,s.current().revision());assertEquals(12,EditorSession.snap(10.1,4,true));assertEquals(10,EditorSession.snap(10.1,4,false));}
    @Test void invalidStylesAndNonFiniteNodeCoordinatesAreRejected(){var d=EditorDefaults.create();var json=EditorCodec.JSON.toJsonTree(d).getAsJsonObject();json.getAsJsonObject("layout").getAsJsonObject("header.sp").addProperty("fontScale",0);assertThrows(IllegalArgumentException.class,()->EditorCodec.decode(json.toString()));}
    @Test void reconciliationMergesIndependentEditsAndReportsSameFieldConflicts(){var base=EditorDefaults.create();var local=new EditorSession(base);local.edit(r->r.getAsJsonObject("layout").getAsJsonObject("header.sp").addProperty("x",12));var remote=new EditorSession(base);remote.edit(r->r.getAsJsonObject("settings").addProperty("grid",8));var result=EditorMerge.reconcile(base,local.current(),remote.current().withRevision(2),true);assertTrue(result.conflicts().isEmpty());assertEquals(12,result.document().layout().get("header.sp").x());assertEquals(8,result.document().settings().grid());assertEquals(2,result.document().revision());remote.edit(r->r.getAsJsonObject("layout").getAsJsonObject("header.sp").addProperty("x",20));result=EditorMerge.reconcile(base,local.current(),remote.current(),false);assertEquals(1,result.conflicts().size());assertEquals(20,result.document().layout().get("header.sp").x());}
    @Test void backupRollbackKeepsNewPublishedIdsDisabledAndGraphArrangementDoesNotOverlap(){var base=EditorDefaults.create();var q=quest("new",List.of(task("a",TaskType.CRAFT,"minecraft:mud_bricks",1)),Match.ALL,List.of(),Match.ALL);var now=with(q);var restored=EditorMerge.rollback(now,base);assertNotNull(restored.quest(q.id()));assertFalse(restored.quest(q.id()).enabled());EditorCodec.validateUpdate(now,restored);var points=GraphGeometry.arrange(now);var values=new ArrayList<>(points.values());for(int i=0;i<values.size();i++)for(int j=i+1;j<values.size();j++)assertTrue(Math.hypot(values.get(i).x()-values.get(j).x(),values.get(i).y()-values.get(j).y())>=100);}
}
